window.marchStdlib = window.marchStdlib || {};
window.marchStdlib["topology.march"] = "-- Topology: the runtime side of a topology app (build step 3 of the\n-- distributed-deploys plan, specs/plans/2026-09-21-distributed-authority-and-deploys-plan.md,\n-- sections 4.1, 4.2 and II.3 / II.6 \"Placement at runtime\").\n--\n-- In a topology app `main` is generated (`march --topology`,\n-- lib/desugar/desugar_topology.ml). It starts the ClusterNode, runs each\n-- pool's hook under `hook` (a watchdog: a hook must return promptly), and\n-- hands this module one `Role` per served role. From then on the NODE owns\n-- its offers (D16): `place` opens the offers the topology places on it and\n-- re-evaluates on every membership change; `drain_on_signal` closes them on\n-- SIGTERM/SIGINT and lets running sessions finish; `supervise_offers` re-offers a\n-- role whose offer (or hosting actor) died, and keeps `main` alive.\n--\n-- Placement rules (4.2), evaluated by every node for itself, with no control\n-- plane:\n--   everywhere()        offered on every node that serves the role (D18);\n--   on_label(label)     offered when this node's labels (MARCH_NODE_LABELS, a\n--                   comma-separated list set by the launcher) include it;\n--   count(n)            offered on n of the eligible live nodes, chosen by\n--                   rendezvous hashing: every node ranks the candidates by\n--                   hash(role, node_id) and offers when it is in the top n (D19);\n--   count_on(l, n)      count(n) among the nodes carrying label l.\n-- \"Eligible\" for a Count role means: a live member (or this node) that serves\n-- the role and carries its label. Other nodes' pools and labels are not in\n-- the membership table, so each eligible node registers a cluster name,\n-- `topo:<role>/<node_id>`, and the ranking reads those names back; a dead\n-- node's names become invisible with its membership. A node that REJOINS\n-- counts only after MARCH_PLACEMENT_SETTLE_MS (default 15000), so a flapping\n-- node does not pull a role back and forth (hysteresis). `count(1)` is not a\n-- lock: during a partition each side may offer, as with any global name.\n--\n-- The hash is SHA-256 (Crypto.sha256), not the plan's BLAKE3: the runtime's\n-- BLAKE3 is not exposed to March code, and the placement only needs a hash\n-- that every node computes identically.\n--\n-- Losing a role is a drain, not a cut: `SessionNode.close_offer` refuses new\n-- invitations and lets the sessions already running finish.\n--\n-- Re-reading the topology (D16, build step 8). `place` installs a SIGHUP\n-- watcher: on SIGHUP the node re-reads MARCH_TOPOLOGY_FILE (the digest,\n-- `.forge/topology.json`, which the reconciler rewrites before signalling)\n-- and applies what changed for the roles its build contains: a new\n-- placement, a role this process's pools no longer serve (its offer is\n-- closed: a drain), a new capacity (the offer is closed and reopened at the\n-- new size). The next evaluation opens and closes offers as for a\n-- membership change; nothing restarts. A role newly served that this build\n-- has no code for is reported, not offered: that needs a rebuild. The node\n-- reports what it applied and the offers it holds to MARCH_TOPOLOGY_STATUS\n-- (`forge topology status` reads it). The reconciler never opens or closes\n-- an offer itself.\nmod Topology do\n  needs IO\n  needs IO.Mut\n  needs IO.Spawn\n  needs IO.Clock\n  needs IO.Signal\n  needs IO.Process\n  needs IO.Console\n  needs IO.NetConnect\n  needs IO.NetListen\n  needs IO.FileRead\n  needs IO.FileWrite\n  needs Session.Live\n  needs ClusterNode.Live\n\n  -- \u2500\u2500 placement rules and roles \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- Constructor names are prefixed: a bare `Count` collided with DataFrame's\n  -- nullary `Count` aggregate in user code that writes it unqualified. Type\n  -- names are prefixed too (`TopoPlacement`, `TopoRole`, ...): March has one\n  -- global type namespace, and a bare `Placement` broke a user program that\n  -- declares its own (test/session/cluster_placement).\n  -- `PlaceNowhere`: not served by this process's pools (after a reload\n  -- moved the role to another pool).\n  type TopoPlacement = PlaceEverywhere | PlaceOn(String) | PlaceCount(Int) | PlaceCountOn(String, Int) | PlaceNowhere\n\n  doc \"Offer the role on every node that serves it (no `place` in the topology).\"\n  fn everywhere() : TopoPlacement do PlaceEverywhere end\n  doc \"Offer the role on the nodes whose MARCH_NODE_LABELS include [label] (`place = { on = label }`).\"\n  fn on_label(label : String) : TopoPlacement do PlaceOn(label) end\n  doc \"Offer the role on [n] of the eligible live nodes, by rendezvous hashing (`place = { count = n }`).\"\n  fn count(n : Int) : TopoPlacement do PlaceCount(n) end\n  doc \"`count(n)` among the nodes carrying [label] (`place = { on = label, count = n }`).\"\n  fn count_on(label : String, n : Int) : TopoPlacement do PlaceCountOn(label, n) end\n\n  -- What an open offer needs to be supervised: the offer, and whether\n  -- whatever serves its sessions is still alive (a hosted role's actor; a\n  -- function role has nothing beyond the offer itself).\n  -- [capacity]: the size it was opened at (0: fixed by the build). [stop]:\n  -- what ends whatever served it once its closed offer has drained (a hosted\n  -- role's actor exits then, 6.1; a function role has nothing to stop).\n  type TopoOpened = { ap : SessionNode.Offer, alive : Int -> Bool, capacity : Int, stop : Int -> () }\n\n  -- One served role: its \"Protocol.Role\" name, its placement, its capacity,\n  -- and how to open one offer of it on this node at a capacity. The\n  -- generated `main` builds these with `offer_role` and `offer_actor_role`\n  -- (capacity from the topology, changeable by a reload); `role` and\n  -- `actor_role` fix the capacity in the code they are given (capacity 0,\n  -- the argument `open` receives is ignored).\n  -- `pinned`: the build places this role itself and a pushed topology does\n  -- not move it (`pinned`, below).\n  type TopoRole = { name : String, place : TopoPlacement, capacity : Int, pinned : Bool,\n                open : Int -> Result(TopoOpened, SessionNode.RunError) }\n\n  doc \"\"\"\n  A role bound to a function (`body = \"M.f\"` in `[roles]`). [open] is the\n  generated `<P>_Run.offer_<R>(io, node, capacity, fn (s, caps..., st) ->\n  M.f(env, s, caps..., st))`.\n  \"\"\"\n  fn role(name : String, place : TopoPlacement, open : () -> Result(SessionNode.Offer, SessionNode.RunError)) : TopoRole do\n    { name: name, place: place, capacity: 0, pinned: false,\n      open: fn _ ->\n        match open() do\n          Ok(o) -> Ok({ ap: o, alive: fn _ -> true, capacity: 0, stop: fn _ -> () })\n          Err(e) -> Err(e)\n        end }\n  end\n\n  doc \"\"\"\n  A role bound to a function, offered at [capacity] sessions: [open] is the\n  generated `fn topology_cap -> <P>_Run.offer_<R>(io, node, topology_cap,\n  ...)`. A reload that changes the role's capacity reopens its offer at the\n  new size.\n  \"\"\"\n  fn offer_role(name : String, place : TopoPlacement, capacity : Int,\n                open : Int -> Result(SessionNode.Offer, SessionNode.RunError)) : TopoRole do\n    { name: name, place: place, capacity: capacity, pinned: false,\n      open: fn cap ->\n        match open(cap) do\n          Ok(o) -> Ok({ ap: o, alive: fn _ -> true, capacity: cap, stop: fn _ -> () })\n          Err(e) -> Err(e)\n        end }\n  end\n\n  doc \"\"\"\n  A role bound to an actor (`actor = \"M.A\"` in `[roles]`, D23): one actor per\n  offer, spawned by [mk] (the generated `fn () -> spawn(M.A, env)`) and handed\n  to [open] (the generated `<P>_Run.offer_hosted_<R>` call whose start,\n  deliver and cancel callbacks forward to it). An actor spawned for an offer\n  that could not be opened is kept for the next attempt rather than spawned\n  again. Supervision re-offers the role when its actor dies. When the offer\n  closes (placement moved the role, its capacity changed, or its protocol\n  did: `reoffer`), the actor keeps serving the sessions it hosts and is\n  stopped once they have all ended (6.1: a protocol change spawns a new\n  hosting actor; the old one drains and exits).\n  \"\"\"\n  fn actor_role(name : String, place : TopoPlacement, mk : () -> Pid(a),\n                open : Pid(a) -> Result(SessionNode.Offer, SessionNode.RunError)) : TopoRole do\n    offer_actor_role(name, place, 0, mk, fn (a, _) -> open(a))\n  end\n\n  doc \"\"\"\n  `actor_role`, offered at [capacity] sessions: [open] takes the actor and\n  the capacity (the generated `fn (topology_a, topology_cap) ->\n  <P>_Run.offer_hosted_<R>(io, node, topology_cap, topology_a, ...)`).\n  \"\"\"\n  fn offer_actor_role(name : String, place : TopoPlacement, capacity : Int, mk : () -> Pid(a),\n                      open : Pid(a) -> Int -> Result(SessionNode.Offer, SessionNode.RunError)) : TopoRole do\n    let spare = Vault.new(\"topology_spare_\" ++ name ++ \"_\" ++ int_to_string(next_id()))\n    { name: name, place: place, capacity: capacity, pinned: false,\n      open: fn cap ->\n        let host = match Vault.get(spare, \"h\") do\n          Some(h) -> h\n          None -> mk()\n        end\n        match open(host, cap) do\n          Ok(o) ->\n            Vault.drop(spare, \"h\")\n            Ok({ ap: o, alive: fn _ -> is_alive(host), capacity: cap, stop: fn _ -> kill(host) })\n          Err(e) ->\n            Vault.set(spare, \"h\", host)\n            Err(e)\n        end }\n  end\n\n  pfn next_id() : Int do\n    let ids : Vault(Int) = Vault.open(\"topology_ids\")\n    Vault.incr(ids, \"n\", 1)\n  end\n\n  -- \u2500\u2500 the pure core: who offers what \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"Labels from a comma-separated list: `\\\"db, public\\\"` is `[\\\"db\\\", \\\"public\\\"]`.\"\n  fn labels_of(s : String) : List(String) do\n    List.filter(List.map(String.split(s, \",\"), String.trim), fn l -> not(String.is_empty(l)))\n  end\n\n  doc \"This node's labels: MARCH_NODE_LABELS, comma-separated (set by the launcher from the overlay).\"\n  fn node_labels() : List(String) do labels_of(Env.get(\"MARCH_NODE_LABELS\", \"\")) end\n\n  doc \"A node's rendezvous score for [role]: every node computes the same one.\"\n  fn score(role_name : String, node_id : String) : String do\n    Crypto.sha256(role_name ++ \"\\n\" ++ node_id)\n  end\n\n  doc \"[ids] ranked for [role_name], best first (highest score; ties by id).\"\n  fn rank(role_name : String, ids : List(String)) : List(String) do\n    let scored = List.map(List.dedup(ids), fn id -> (score(role_name, id), id))\n    let sorted = List.sort_by(scored, fn (a, b) ->\n      match (a, b) do\n        ((sa, ia), (sb, ib)) -> if sa == sb do ia < ib else sa > sb end\n      end)\n    List.map(sorted, fn p -> match p do (_, id) -> id end)\n  end\n\n  doc \"Whether this node may take part in [p] at all: it carries the label, if any.\"\n  fn eligible_here(p : TopoPlacement, labels : List(String)) : Bool do\n    match p do\n      PlaceEverywhere -> true\n      PlaceOn(l) -> List.member(labels, l)\n      PlaceCount(_) -> true\n      PlaceCountOn(l, _) -> List.member(labels, l)\n      PlaceNowhere -> false\n    end\n  end\n\n  doc \"Whether [p] ranks nodes (and so needs the eligible set).\"\n  fn ranked(p : TopoPlacement) : Bool do\n    match p do\n      PlaceCount(_) -> true\n      PlaceCountOn(_, _) -> true\n      _ -> false\n    end\n  end\n\n  doc \"\"\"\n  Whether node [me], with [labels], offers [role_name] under [p], given the\n  settled eligible nodes [eligible] (other nodes; [me] is added when it is\n  eligible itself).\n  \"\"\"\n  fn wants(p : TopoPlacement, role_name : String, me : String, labels : List(String), eligible : List(String)) : Bool do\n    if not(eligible_here(p, labels)) do false\n    else\n      match p do\n        PlaceCount(n) -> List.member(List.take(rank(role_name, Cons(me, eligible)), n), me)\n        PlaceCountOn(_, n) -> List.member(List.take(rank(role_name, Cons(me, eligible)), n), me)\n        _ -> true\n      end\n    end\n  end\n\n  doc \"A member that rejoined at [rejoined_at] counts again once [settle_ms] have passed.\"\n  fn settled(now : Int, rejoined_at : Option(Int), settle_ms : Int) : Bool do\n    match rejoined_at do\n      None -> true\n      Some(t) -> now - t >= settle_ms\n    end\n  end\n\n  doc \"How many nodes [p] places on (n for a `count = n` role; 0 for an unranked one).\"\n  fn count_of(p : TopoPlacement) : Int do\n    match p do\n      PlaceCount(n) -> n\n      PlaceCountOn(_, n) -> n\n      _ -> 0\n    end\n  end\n\n  doc \"\"\"\n  Whether this node may OPEN ranked role [p] it now ranks for (it is not\n  offering it yet), at [now]: the settle rule its peers apply to it, applied\n  by the node itself. A node that started at [started] and has not yet\n  merged a peer's registry ([synced] false) knows no other node's marker, so\n  it opens nothing ranked until it has, or until [settle_ms] have passed\n  (seeds unreachable: a lone node still takes its roles). A node that a peer\n  last showed as rejoining at [rejoined_at] (`ClusterNode.rejoined_at`) is\n  not counted by those peers for [settle_ms], so for that long it opens the\n  role only if the [others] other non-dead nodes marked eligible cannot fill\n  its count without it. Never stops a node keeping an offer it holds.\n  \"\"\"\n  fn may_open(p : TopoPlacement, others : Int, now : Int, started : Int, synced : Bool,\n              rejoined_at : Option(Int), settle_ms : Int) : Bool do\n    if not(ranked(p)) do true\n    else if not(synced) && now - started < settle_ms do false\n    else\n      match rejoined_at do\n        Some(t) -> if now - t < settle_ms do others < count_of(p) else true end\n        None -> true\n      end\n    end end\n  end\n\n  doc \"The name an eligible node registers for a ranked role.\"\n  fn marker(role_name : String, node_id : String) : String do\n    \"topo:\" ++ role_name ++ \"/\" ++ node_id\n  end\n\n  doc \"\"\"\n  The node ids behind every `marker(role_name, id)` in [names], in [names]\n  order; names that are not markers of [role_name] are ignored (duplicates\n  are kept).\n\n  ## Examples\n\n      Topology.marked(\"P.Db\", [\"topo:P.Db/n1\", \"other\", \"topo:P.Web/n2\", \"topo:P.Db/n3\"])\n      -- [\"n1\", \"n3\"]\n  \"\"\"\n  fn marked(role_name : String, names : List(String)) : List(String) do\n    let prefix = \"topo:\" ++ role_name ++ \"/\"\n    let k = String.byte_size(prefix)\n    List.filter_map(names, fn nm ->\n      if String.starts_with(nm, prefix) do Some(String.slice(nm, k, String.byte_size(nm) - k)) else None end)\n  end\n\n  pfn settle_ms() : Int do Env.get_int(\"MARCH_PLACEMENT_SETTLE_MS\", 15000) end\n  pfn tick_ms() : Int do Env.get_int(\"MARCH_PLACEMENT_TICK_MS\", 200) end\n  pfn hook_timeout_ms() : Int do Env.get_int(\"MARCH_HOOK_TIMEOUT_MS\", 10000) end\n\n  -- \u2500\u2500 per-node state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- The process a node's placement markers are bound to.\n  -- A field name no other stdlib or user record is likely to share: a\n  -- declared record type is found by its SHAPE in places (the `@[remote]`\n  -- codec choice), and `{ n : Int }` made a user's `type Hit = { n : Int }`\n  -- ambiguous.\n  type TopoAnchorState = { topology_anchor_marks : Int }\n\n  actor Anchor do\n    state { topology_anchor_marks : Int }\n    init  { topology_anchor_marks: 0 }\n    on Nop() do state end\n    -- The placement loop, restarted from here after a deploy (build step 9):\n    -- a task runs the code of the epoch it was spawned in, and this actor has\n    -- passed its marker, so the loop it spawns runs the new code -- opening\n    -- a changed protocol's offer under its new fingerprint.\n    on Respawn(node : Cap(ClusterNode.Live), st : TopoState) do\n      let _ = task_spawn(fn _ -> do\n        reoffer_with(node, st)\n        place_loop(node, st)\n      end)\n      state\n    end\n  end\n\n  -- Everything `place`, `drain_on_signal` and `supervise_offers` share,\n  -- found by the node's id so the three need only the node.\n  type TopoState = { meta : Vault(Int), strs : Vault(String), offers : Vault(TopoOpened), draining : Vault(TopoOpened),\n                 roles : Vault(List(TopoRole)), anchor : Vault(Pid(TopoAnchorState)) }\n\n  pfn state_of(node : Cap(ClusterNode.Live)) : TopoState do\n    let k = ClusterNode.node_id(node)\n    { meta: Vault.open(\"topology_meta_\" ++ k), strs: Vault.open(\"topology_strs_\" ++ k),\n      offers: Vault.open(\"topology_offers_\" ++ k),\n      draining: Vault.open(\"topology_draining_\" ++ k), roles: Vault.open(\"topology_roles_\" ++ k),\n      anchor: Vault.open(\"topology_anchor_\" ++ k) }\n  end\n\n  pfn anchor(st : TopoState) : Pid(TopoAnchorState) do\n    match Vault.get(st.anchor, \"a\") do\n      Some(a) -> a\n      None ->\n        let a = spawn(Anchor)\n        Vault.set(st.anchor, \"a\", a)\n        a\n    end\n  end\n\n  -- Reports go to stdout, prefixed: `print_stderr` exists in both backends\n  -- but not in the typechecker's builtin table.\n  -- The node's name for messages: its own membership entry, else its id.\n  pfn label(node : Cap(ClusterNode.Live)) : String do\n    let me = ClusterNode.node_id(node)\n    match List.find(ClusterNode.all_members(node), fn m -> m.node_id == me) do\n      Some(m) -> m.name\n      None -> me\n    end\n  end\n\n  pfn report(msg : String) : () do println(\"topology: \" ++ msg) end\n\n  -- \u2500\u2500 placement \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Open the offers the topology places on [node], one per entry of [roles],\n  and keep them placed: a task re-evaluates every MARCH_PLACEMENT_TICK_MS\n  (default 200 ms) against the current membership, opening a role this node\n  now ranks for and closing (draining) one it no longer does. Membership\n  events are recorded as they arrive; a node that rejoins counts after the\n  settling period. This node applies that period to itself too (`may_open`):\n  it opens no ranked role before its first registry sync (bounded by\n  MARCH_PLACEMENT_SETTLE_MS), and while a peer counts it as rejoined it\n  leaves a ranked role to the nodes already offering it. Returns once the\n  first evaluation has opened the offers it may open now (a ranked one held\n  back opens on a later tick).\n  \"\"\"\n  fn place(node : Cap(ClusterNode.Live), roles : List(TopoRole)) : () do\n    let st = state_of(node)\n    Vault.set(st.roles, \"roles\", roles)\n    Vault.set(st.roles, \"base\", roles)\n    -- When placement began here: the bound on waiting for a first registry\n    -- sync (`may_open`).\n    if Vault.get(st.meta, \"started\") == None do Vault.set(st.meta, \"started\", unix_time_ms()) else () end\n    -- A restarted node comes back on the topology last pushed to it (plan\n    -- 6.5): the reload server restored and re-verified its signed copy\n    -- before `main` ran.  Only that copy: the unsigned file is what the\n    -- build was started with, and is read on SIGHUP as before.\n    let _ = match process_env(\"MARCH_TOPOLOGY_VERIFIED_FILE\") do\n      Some(p) -> if File.exists(p) do apply_file(st, p, \"start\") else false end\n      None -> false\n    end\n    Signal.watch(Signal.Hup, fn -> reload(node))\n    let meta = st.meta\n    let _ = ClusterNode.subscribe(node, fn ev ->\n      match ev do\n        ClusterNode.NodeRejoined(i) -> Vault.set(meta, \"r:\" ++ i.node_id, unix_time_ms())\n        _ -> ()\n      end)\n    reconcile(node, st)\n    write_status(node, st)\n    let _ = task_spawn(fn _ -> place_loop(node, st))\n    ()\n  end\n\n  @[diverges] pfn place_loop(node : Cap(ClusterNode.Live), st : TopoState) : Int do\n    sleep_ms(tick_ms())\n    if Vault.get(st.meta, \"closing\") != None do 0\n    else if Vault.get(st.meta, \"stopped\") != None do 0\n    -- A deploy made this loop's epoch old: hand over to a loop on the new\n    -- code (the anchor's, which has moved past its marker) and end.\n    else if epoch_draining() do\n      let _ = send(anchor(st), Respawn(node, st))\n      0\n    else\n      reconcile(node, st)\n      write_status(node, st)\n      place_loop(node, st)\n    end end end\n  end\n\n  -- The other nodes eligible for [r], settled, as this node sees them.\n  pfn eligible_others(node : Cap(ClusterNode.Live), st : TopoState, r : TopoRole, now : Int) : List(String) do\n    -- A suspect member still counts: a role moves only once SWIM declares\n    -- its node Dead (4.2), not on every missed probe.\n    let alive = List.filter_map(ClusterNode.all_members(node), fn m ->\n      match m.status do\n        Membership.Dead -> None\n        _ -> Some(m.node_id)\n      end)\n    let settle = settle_ms()\n    List.filter(marked(r.name, ClusterNode.names(node)), fn id ->\n      id != ClusterNode.node_id(node) && List.member(alive, id) && settled(now, Vault.get(st.meta, \"r:\" ++ id), settle))\n  end\n\n  -- The other nodes marked eligible for [r] that are not Dead here (one\n  -- not yet in the member table counts: its marker came from a peer that\n  -- knows it), settled or not: those a rejoining node defers to.\n  pfn marked_others(node : Cap(ClusterNode.Live), r : TopoRole) : Int do\n    let me = ClusterNode.node_id(node)\n    let dead = List.filter_map(ClusterNode.all_members(node), fn m ->\n      match m.status do\n        Membership.Dead -> Some(m.node_id)\n        _ -> None\n      end)\n    List.length(List.filter(marked(r.name, ClusterNode.names(node)), fn id ->\n      id != me && not(List.member(dead, id))))\n  end\n\n  -- `may_open` for [r] on [node] now.\n  pfn may_open_here(node : Cap(ClusterNode.Live), st : TopoState, now : Int, r : TopoRole) : Bool do\n    if not(ranked(r.place)) do true\n    else\n      may_open(r.place, marked_others(node, r), now, Vault.get_or(st.meta, \"started\", now),\n               ClusterNode.registry_synced(node), ClusterNode.rejoined_at(node), settle_ms())\n    end\n  end\n\n  doc \"\"\"\n  Re-evaluate [node]'s placement now, as the next tick would. For tests that\n  drive membership through a fake dictionary and should not wait for a tick\n  (run them with a long MARCH_PLACEMENT_TICK_MS).\n  \"\"\"\n  fn reconcile_now(node : Cap(ClusterNode.Live)) : () do reconcile(node, state_of(node)) end\n\n  pfn reconcile(node : Cap(ClusterNode.Live), st : TopoState) : () do\n    let labels = node_labels()\n    let now = unix_time_ms()\n    let roles = Vault.get_or(st.roles, \"roles\", Nil)\n    List.each(roles, fn r -> reconcile_role(node, st, labels, now, r))\n    watch_draining(st, now)\n  end\n\n  pfn reconcile_role(node : Cap(ClusterNode.Live), st : TopoState, labels : List(String), now : Int, r : TopoRole) : () do\n    let here = eligible_here(r.place, labels)\n    if ranked(r.place) do mark(node, st, r.name, here) else () end\n    let others = if ranked(r.place) do eligible_others(node, st, r, now) else Nil end\n    let want = wants(r.place, r.name, ClusterNode.node_id(node), labels, others)\n    match Vault.get(st.offers, r.name) do\n      None ->\n        if want && may_open_here(node, st, now, r) do\n          Vault.drop(st.meta, \"d:\" ++ r.name)\n          open_role(node, st, now, r)\n        else if want do\n          -- Report a rejoining node's deferral once, not every tick (the\n          -- wait for a first sync is silent: it normally lasts a link's\n          -- handshake).\n          if ClusterNode.registry_synced(node) && Vault.get(st.meta, \"d:\" ++ r.name) == None do\n            Vault.set(st.meta, \"d:\" ++ r.name, 1)\n            report(r.name ++ \": \" ++ label(node) ++ \" ranks for it but a peer counts it as rejoined and it is settling;\"\n                   ++ \" leaving it to the nodes already counted\")\n          else () end\n        else clear_conflict(st, r.name) end end\n      Some(o) ->\n        if not(want) do\n          report(r.name ++ \": no longer placed on \" ++ label(node) ++ \"; draining its offer\")\n          retire(st, r.name, o)\n        else if r.capacity > 0 && o.capacity != r.capacity do\n          report(r.name ++ \": capacity \" ++ int_to_string(o.capacity) ++ \" -> \" ++ int_to_string(r.capacity)\n                 ++ \"; draining its offer and opening one at the new size\")\n          retire(st, r.name, o)\n        else if Vault.get(st.meta, \"supervise\") != None && not(healthy(o)) do\n          report(r.name ++ \": its offer or hosting actor died; offering it again\")\n          retire(st, r.name, o)\n        else () end end end\n    end\n  end\n\n  -- Register (or release) this node's marker for a ranked role.\n  pfn mark(node : Cap(ClusterNode.Live), st : TopoState, role_name : String, here : Bool) : () do\n    let name = marker(role_name, ClusterNode.node_id(node))\n    let held = Option.is_some(ClusterNode.lookup(node, name))\n    if here && not(held) do\n      let _ = ClusterNode.register(node, name, anchor(st))\n      ()\n    else if not(here) && held do ClusterNode.unregister(node, name)\n    else () end end\n  end\n\n  -- An open refused with `AlreadyOffered` means the offer's endpoint name\n  -- (SessionNode names it by protocol, role, fingerprint and node, NOT by\n  -- the Topology role) is held on this node. That is one of two things:\n  --\n  -- * TRANSIENT: an offer on this node was closed moments ago (placement\n  --   moved its role, its capacity changed, supervision or a deploy retired\n  --   it) and the node actor has not released its name yet; the name is free\n  --   within a turn or two. Within `conflict_grace_ms` of the node's last\n  --   retirement (`rt`, set by `retire`) the refusal is retried every tick\n  --   without a word, as it always was. This covers a role reopening after\n  --   its own offer closed, and a role whose conflicting holder just closed.\n  -- * A CONFLICT: anything else, above all two roles placed on this node\n  --   that serve the same protocol role through the same offer function --\n  --   they want ONE endpoint name, so the second can never be offered while\n  --   the first is. It is reported once, recorded in the status file\n  --   (`conflict <role> held-by <roles>`), and retried only when this node's\n  --   set of open offers changes, an offer closes (the holder may be gone),\n  --   or after a backoff that doubles from 1 s to 60 s -- never silently\n  --   every tick.\n  pfn conflict_grace_ms() : Int do Env.get_int(\"MARCH_PLACEMENT_CONFLICT_GRACE_MS\", 5000) end\n\n  -- This node's open offers, as a string that changes whenever one opens or\n  -- closes (a reopened role gets a fresh offer id).\n  pfn offers_signature(st : TopoState) : String do\n    String.join(List.sort_by(List.map(Vault.all(st.offers), fn kv ->\n      match kv do (name, o) -> name ++ \"=\" ++ o.ap.id end), fn (a, b) -> a < b), \",\")\n  end\n\n  pfn clear_conflict(st : TopoState, role_name : String) : () do\n    Vault.drop(st.strs, \"x:\" ++ role_name)\n    Vault.drop(st.strs, \"xs:\" ++ role_name)\n    Vault.drop(st.meta, \"xn:\" ++ role_name)\n    Vault.drop(st.meta, \"xb:\" ++ role_name)\n  end\n\n  pfn open_role(node : Cap(ClusterNode.Live), st : TopoState, now : Int, r : TopoRole) : () do\n    let conflicted = Vault.get(st.strs, \"x:\" ++ r.name) != None\n    let recent = match Vault.get(st.meta, \"rt\") do\n      Some(t) -> now - t < conflict_grace_ms()\n      None -> false\n    end\n    -- A known conflict waits for the offers to change or the backoff to pass.\n    let due = not(conflicted) || recent\n              || Vault.get(st.strs, \"xs:\" ++ r.name) != Some(offers_signature(st))\n              || now >= Vault.get_or(st.meta, \"xn:\" ++ r.name, 0)\n    if not(due) do () else\n      match (r.open)(r.capacity) do\n        Ok(o) ->\n          Vault.drop(st.meta, \"e:\" ++ r.name)\n          Vault.set(st.offers, r.name, o)\n          if conflicted do\n            report(r.name ++ \": its endpoint is free again; offered on \" ++ label(node))\n            clear_conflict(st, r.name)\n          else () end\n        Err(SessionNode.AlreadyOffered(idx)) ->\n          if recent do () else on_conflict(node, st, now, r.name, idx, conflicted) end\n        Err(e) ->\n          -- Report a failure once, not every tick.\n          if Vault.get(st.meta, \"e:\" ++ r.name) == None do\n            Vault.set(st.meta, \"e:\" ++ r.name, 1)\n            report(r.name ++ \": could not offer: \" ++ SessionNode.run_error_message(e))\n          else () end\n      end\n    end\n  end\n\n  -- Record (and, the first time, report) that [role_name]'s endpoint is held\n  -- by another offer on this node, and schedule the next try.\n  pfn on_conflict(node : Cap(ClusterNode.Live), st : TopoState, now : Int, role_name : String, idx : Int, known : Bool) : () do\n    -- The likely holders: this node's other open offers of a role with the\n    -- same index (the refusal names only the index, not the protocol).\n    let holders = List.sort_by(List.filter_map(Vault.all(st.offers), fn kv ->\n      match kv do\n        (name, o) -> if name != role_name && o.ap.my_role == idx do Some(name) else None end\n      end), fn (a, b) -> a < b)\n    let held_by = if List.is_empty(holders) do \"unknown\" else String.join(holders, \",\") end\n    let doubled = Vault.get_or(st.meta, \"xb:\" ++ role_name, 1000) * 2\n    let backoff = if not(known) do 1000 else if doubled > 60000 do 60000 else doubled end end\n    Vault.set(st.meta, \"xb:\" ++ role_name, backoff)\n    Vault.set(st.meta, \"xn:\" ++ role_name, now + backoff)\n    Vault.set(st.strs, \"xs:\" ++ role_name, offers_signature(st))\n    Vault.set(st.strs, \"x:\" ++ role_name, held_by)\n    if not(known) do\n      let who = if List.is_empty(holders) do \"another offer on this node\"\n                else \"role \" ++ String.join(holders, \", \") end\n      report(role_name ++ \": cannot be offered on \" ++ label(node) ++ \": its endpoint name is held by \" ++ who\n             ++ \" (two roles serving the same protocol role share one endpoint per node: place them on\"\n             ++ \" different nodes or give each its own protocol); retrying when this node's offers change, with backoff\")\n    else () end\n  end\n\n  doc \"\"\"\n  Re-open each of [node]'s open offers with the code now running\n  (distributed-deploys build step 9): an offer whose protocol fingerprint\n  changed is opened again under the new one (a hosted role with a fresh\n  actor) and the old offer is closed; its sessions finish on the old\n  version and a hosting actor exits once they have (6.1). An offer whose\n  fingerprint did not change stays as it is (the new offer's name is\n  already taken). The placement loop runs this itself after a deploy; call\n  it directly only from a test.\n  \"\"\"\n  fn reoffer(node : Cap(ClusterNode.Live)) : () do reoffer_with(node, state_of(node)) end\n\n  pfn reoffer_with(node : Cap(ClusterNode.Live), st : TopoState) : () do\n    let roles = Vault.get_or(st.roles, \"roles\", Nil)\n    List.each(roles, fn r ->\n      match Vault.get(st.offers, r.name) do\n        None -> ()\n        Some(o) ->\n          match (r.open)(if o.capacity > 0 do o.capacity else r.capacity end) do\n            Ok(fresh) ->\n              if fresh.ap.fingerprint == o.ap.fingerprint do\n                -- Opened under another name with the same version (should not\n                -- happen: the name carries the fingerprint); keep one.\n                SessionNode.close_offer(fresh.ap)\n                (fresh.stop)(0)\n              else\n                report(r.name ++ \": protocol changed on \" ++ label(node)\n                       ++ \"; offering the new version and draining the old one\")\n                retire(st, r.name, o)\n                Vault.set(st.offers, r.name, fresh)\n              end\n            -- Same fingerprint: this version is already offered.\n            Err(SessionNode.AlreadyOffered(_)) -> ()\n            Err(e) -> report(r.name ++ \": could not offer its new version: \" ++ SessionNode.run_error_message(e))\n          end\n      end)\n  end\n\n  -- Close [o] (sessions already running finish) and keep it for the drain.\n  pfn retire(st : TopoState, role_name : String, o : TopoOpened) : () do\n    SessionNode.close_offer(o.ap)\n    Vault.drop(st.offers, role_name)\n    let key = role_name ++ \"#\" ++ int_to_string(next_id())\n    Vault.set(st.draining, key, o)\n    let now = unix_time_ms()\n    Vault.set(st.meta, \"t:\" ++ key, now)\n    -- Its name is released asynchronously: an `AlreadyOffered` shortly after\n    -- is this offer's name, not a conflict (`open_role`).\n    Vault.set(st.meta, \"rt\", now)\n  end\n\n  -- An offer closed while the node keeps running (placement or a reload\n  -- moved its role) drains under the topology's deadlines: its sessions are\n  -- reported once still running at the soft deadline, and again at the hard\n  -- one. They are not cut: cancelling one offer's sessions needs a\n  -- SessionNode API that does not exist yet (a process-wide drain on\n  -- SIGTERM still ends at `drain_on_signal`'s hard deadline). A drained\n  -- offer is forgotten.\n  pfn watch_draining(st : TopoState, now : Int) : () do\n    let soft = Vault.get_or(st.meta, \"drain_soft\", 30000)\n    let hard = Vault.get_or(st.meta, \"drain_hard\", 120000)\n    List.each(Vault.all(st.draining), fn kv ->\n      match kv do\n        (key, o) ->\n          let n = active(o)\n          let since = now - Vault.get_or(st.meta, \"t:\" ++ key, now)\n          if n == 0 do\n            -- Drained: whatever served it (a hosting actor) is done.\n            (o.stop)(0)\n            Vault.drop(st.draining, key)\n            Vault.drop(st.meta, \"t:\" ++ key)\n            Vault.drop(st.meta, \"w:\" ++ key)\n          else\n            let warned = Vault.get_or(st.meta, \"w:\" ++ key, 0)\n            if since >= hard && warned < 2 do\n              Vault.set(st.meta, \"w:\" ++ key, 2)\n              report(key ++ \": hard drain deadline passed with \" ++ int_to_string(n) ++ \" session(s) still running on its closed offer\")\n            else if since >= soft && warned < 1 do\n              Vault.set(st.meta, \"w:\" ++ key, 1)\n              report(key ++ \": soft drain deadline passed with \" ++ int_to_string(n) ++ \" session(s) still running on its closed offer\")\n            else () end end\n          end\n      end)\n  end\n\n  pfn healthy(o : TopoOpened) : Bool do\n    is_alive(o.ap.worker) && (o.alive)(0)\n  end\n\n  doc \"The roles [node] offers right now, by name, sorted.\"\n  fn offered(node : Cap(ClusterNode.Live)) : List(String) do\n    let st = state_of(node)\n    List.sort_by(Vault.keys(st.offers), fn (a, b) -> a < b)\n  end\n\n  doc \"Does [node] offer [role_name] right now? (For a `count = 1` role: is this node the one that serves it.)\"\n  fn offering(node : Cap(ClusterNode.Live), role_name : String) : Bool do\n    List.member(offered(node), role_name)\n  end\n\n  doc \"\"\"\n  The members that currently mark themselves eligible for the ranked role\n  [role_name] (a `place = { on = ..., count = n }` role), this node included\n  when it is: its candidates, whichever of them ranks first. The control plane\n  finds its standbys and its leader with it. A dead member is left out.\n  \"\"\"\n  fn role_candidates(node : Cap(ClusterNode.Live), role_name : String) : List(Membership.Member) do\n    let ids = marked(role_name, ClusterNode.names(node))\n    List.filter(ClusterNode.all_members(node), fn m ->\n      List.member(ids, m.node_id) && (match m.status do\n        Membership.Dead -> false\n        _ -> true\n      end))\n  end\n\n  doc \"The actor answering invitations for [role_name]'s open offer on [node], if one is open.\"\n  fn offer_worker(node : Cap(ClusterNode.Live), role_name : String) : Option(Pid(SessionNode.OfferCount)) do\n    let st = state_of(node)\n    match Vault.get(st.offers, role_name) do\n      Some(o) -> Some(o.ap.worker)\n      None -> None\n    end\n  end\n\n  -- Sessions still running under [o].\n  pfn active(o : TopoOpened) : Int do\n    match get_actor_field(o.ap.worker, \"active\") do\n      Some(n) -> n\n      None -> 0\n    end\n  end\n\n  doc \"Sessions still running on [node]'s offers, open or draining.\"\n  fn running(node : Cap(ClusterNode.Live)) : Int do\n    let st = state_of(node)\n    let sum = fn (acc, kv) -> match kv do (_, o) -> acc + active(o) end\n    List.fold_left(Vault.all(st.draining), List.fold_left(Vault.all(st.offers), 0, sum), sum)\n  end\n\n  -- What the SIGTERM drain waits for: the sessions on [node]'s offers and\n  -- those it started itself (`SessionNode.initiated`: an `initiate_R` from a\n  -- hook or a role body, a hand-written `cluster_R`). A session with both\n  -- ends on this node counts twice; the drain asks only whether any runs.\n  pfn unfinished(node : Cap(ClusterNode.Live)) : Int do\n    running(node) + SessionNode.initiated(node)\n  end\n\n  -- \u2500\u2500 re-reading the topology (SIGHUP) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"A placement as the topology writes it, for reports.\"\n  fn placement_text(p : TopoPlacement) : String do\n    match p do\n      PlaceEverywhere -> \"everywhere\"\n      PlaceOn(l) -> \"on \" ++ l\n      PlaceCount(n) -> \"count \" ++ int_to_string(n)\n      PlaceCountOn(l, n) -> \"count \" ++ int_to_string(n) ++ \" on \" ++ l\n      PlaceNowhere -> \"not served here\"\n    end\n  end\n\n  pfn json_int(j : Option(Json.JsonValue)) : Option(Int) do\n    match j do\n      Some(Json.Number(f)) -> Some(float_to_int(f))\n      _ -> None\n    end\n  end\n\n  pfn json_str(j : Option(Json.JsonValue)) : Option(String) do\n    match j do\n      Some(Json.Str(s)) -> Some(s)\n      _ -> None\n    end\n  end\n\n  pfn json_list(j : Option(Json.JsonValue)) : List(Json.JsonValue) do\n    match j do\n      Some(Json.Array(xs)) -> xs\n      _ -> Nil\n    end\n  end\n\n  doc \"\"\"\n  A digest's `place` object as a placement: null is everywhere (D18),\n  `{ on }`, `{ count }`, or both.\n  \"\"\"\n  fn placement_of_json(j : Option(Json.JsonValue)) : TopoPlacement do\n    match j do\n      Some(Json.Object(_)) ->\n        let pj = Option.unwrap_or(j, Json.Null)\n        match (json_str(Json.get(pj, \"on\")), json_int(Json.get(pj, \"count\"))) do\n          (Some(l), Some(n)) -> PlaceCountOn(l, n)\n          (Some(l), None) -> PlaceOn(l)\n          (None, Some(n)) -> PlaceCount(n)\n          (None, None) -> PlaceEverywhere\n        end\n      _ -> PlaceEverywhere\n    end\n  end\n\n  -- A role as the digest describes it: (name, placement, capacity).\n  type TopoDesired = { d_name : String, d_place : TopoPlacement, d_capacity : Int }\n\n  doc \"\"\"\n  What the digest [text] asks of this process: for each role one of\n  [pools] serves, its placement and capacity (a role no such pool serves is\n  absent); the drain deadlines; and an error for text that is not a\n  version-1 digest. Defaults for missing fields: capacity 64, soft drain\n  30000 ms, hard drain 120000 ms.\n  \"\"\"\n  fn desired_of(text : String, pools : String -> Bool) : Result((List(TopoDesired), Int, Int), String) do\n    match Json.parse(text) do\n      Err(e) -> Err(\"not JSON: \" ++ e)\n      Ok(dj) ->\n        if json_int(Json.get(dj, \"version\")) != Some(1) do Err(\"not a version-1 topology digest\")\n        else\n          let served = List.flat_map(json_list(Json.get(dj, \"pools\")), fn p ->\n            match json_str(Json.get(p, \"name\")) do\n              Some(n) ->\n                if pools(n) do\n                  List.filter_map(json_list(Json.get(p, \"serves\")), fn r -> json_str(Some(r)))\n                else Nil end\n              None -> Nil\n            end)\n          let roles = List.filter_map(json_list(Json.get(dj, \"roles\")), fn r ->\n            match json_str(Json.get(r, \"name\")) do\n              Some(n) ->\n                if List.member(served, n) do\n                  Some({ d_name: n, d_place: placement_of_json(Json.get(r, \"place\")),\n                         d_capacity: Option.unwrap_or(json_int(Json.get(r, \"capacity\")), 64) })\n                else None end\n              None -> None\n            end)\n          let drain = Option.unwrap_or(Json.get(dj, \"drain\"), Json.Null)\n          let soft = Option.unwrap_or(json_int(Json.get(drain, \"soft_ms\")), 30000)\n          let hard = Option.unwrap_or(json_int(Json.get(drain, \"hard_ms\")), 120000)\n          Ok((roles, soft, hard))\n        end\n    end\n  end\n\n  doc \"\"\"\n  [base] (the roles this build contains, as the generated `main` placed\n  them) under [desired]: a pinned role is left as the build placed it; a\n  role the digest no longer serves here is `PlaceNowhere`; otherwise its\n  placement and (unless fixed by the build, capacity 0) its capacity come\n  from the digest.\n  \"\"\"\n  fn apply_desired(base : List(TopoRole), desired : List(TopoDesired)) : List(TopoRole) do\n    List.map(base, fn r ->\n      if r.pinned do r else\n        match List.find(desired, fn d -> d.d_name == r.name) do\n          None -> { r with place: PlaceNowhere }\n          Some(d) -> { r with place: d.d_place, capacity: if r.capacity == 0 do 0 else d.d_capacity end }\n        end\n      end)\n  end\n\n  doc \"\"\"\n  [r], pinned: a pushed topology leaves its placement and capacity as the\n  build set them (`apply_desired`). For roles the generated `main` adds\n  itself and a topology digest cannot name, such as the control plane's\n  `Ctl.Control` (placed from `[control]`): without the pin, every re-read of\n  the topology (a signed push, SIGHUP, or a restart onto a verified copy)\n  would place it nowhere, and the cluster would lose its leader.\n  \"\"\"\n  fn pinned(r : TopoRole) : TopoRole do\n    { r with pinned: true }\n  end\n\n  pfn find_role(roles : List(TopoRole), name : String) : Option(TopoRole) do\n    List.find(roles, fn r -> r.name == name)\n  end\n\n  pfn report_change(before : List(TopoRole), r : TopoRole) : () do\n    match find_role(before, r.name) do\n      Some(b) ->\n        if placement_text(b.place) != placement_text(r.place) do\n          report(r.name ++ \": placement \" ++ placement_text(b.place) ++ \" -> \" ++ placement_text(r.place))\n        else () end\n      None -> ()\n    end\n  end\n\n  pfn report_unbuilt(base : List(TopoRole), d : TopoDesired) : () do\n    match find_role(base, d.d_name) do\n      Some(_) -> ()\n      None -> report(d.d_name ++ \": now served by this node's pool, but this build has no code for it; rebuild and restart to offer it\")\n    end\n  end\n\n  -- Where the topology to apply comes from (DD step 12-pre).  The reload\n  -- server writes every signature-checked TOPOLOGY push to\n  -- MARCH_TOPOLOGY_VERIFIED_FILE; when that copy exists it wins over the\n  -- unsigned MARCH_TOPOLOGY_FILE, so the signed push is what takes effect.\n  -- With MARCH_HCR_REQUIRE_RELEASE=1 the unsigned file is never read.\n  pfn topology_source() : Result(String, String) do\n    let verified = match process_env(\"MARCH_TOPOLOGY_VERIFIED_FILE\") do\n      Some(p) -> if File.exists(p) do Some(p) else None end\n      None -> None\n    end\n    match verified do\n      Some(p) -> Ok(p)\n      None ->\n        if process_env(\"MARCH_HCR_REQUIRE_RELEASE\") == Some(\"1\") do\n          Err(\"no signed topology has been pushed (MARCH_HCR_REQUIRE_RELEASE=1 ignores MARCH_TOPOLOGY_FILE)\")\n        else\n          match process_env(\"MARCH_TOPOLOGY_FILE\") do\n            None -> Err(\"MARCH_TOPOLOGY_FILE is not set; there is no topology to re-read\")\n            Some(p) -> Ok(p)\n          end\n        end\n    end\n  end\n\n  -- Parse [path] and take its placement, capacity and drain deadlines for\n  -- the roles this build contains.  True when applied; a file that cannot be\n  -- read or parsed changes nothing and is reported under [why].\n  pfn apply_file(st : TopoState, path : String, why : String) : Bool do\n    match File.read(path) do\n      Err(_) ->\n        report(why ++ \": could not read \" ++ path ++ \"; placement unchanged\")\n        false\n      Ok(text) ->\n        match desired_of(text, fn p -> runs_pool(p)) do\n          Err(e) ->\n            report(why ++ \": \" ++ path ++ \": \" ++ e ++ \"; placement unchanged\")\n            false\n          Ok((desired, soft, hard)) ->\n            let base : List(TopoRole) = Vault.get_or(st.roles, \"base\", Nil)\n            let before : List(TopoRole) = Vault.get_or(st.roles, \"roles\", Nil)\n            let after = apply_desired(base, desired)\n            List.each(after, fn r -> report_change(before, r))\n            List.each(desired, fn d -> report_unbuilt(base, d))\n            Vault.set(st.meta, \"drain_soft\", soft)\n            Vault.set(st.meta, \"drain_hard\", hard)\n            Vault.set(st.roles, \"roles\", after)\n            Vault.set(st.strs, \"applied\", Crypto.sha256(text))\n            report(\"topology re-read from \" ++ path)\n            true\n        end\n    end\n  end\n\n  doc \"\"\"\n  Re-read the topology now, as SIGHUP does: the signature-checked copy the\n  reload server keeps (MARCH_TOPOLOGY_VERIFIED_FILE) when there is one, else\n  MARCH_TOPOLOGY_FILE, is parsed and the roles this build contains take\n  their placement and capacity from it; the next evaluation (run at once)\n  opens and drains offers to match. A file that cannot be read or parsed\n  changes nothing and is reported.\n  \"\"\"\n  fn reload(node : Cap(ClusterNode.Live)) : () do\n    let st = state_of(node)\n    if Vault.get(st.meta, \"closing\") != None do () else\n      match topology_source() do\n        Err(e) -> report(\"SIGHUP: \" ++ e)\n        Ok(path) ->\n          if apply_file(st, path, \"SIGHUP\") do\n            reconcile(node, st)\n            write_status(node, st)\n          else () end\n      end\n    end\n  end\n\n  -- \u2500\u2500 status (for the reconciler) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  What this node reports to the reconciler: its name, the digest it applied\n  (sha256, or `compiled` before any reload), its offers, how many closed\n  offers are still draining, the sessions running on them all, and a\n  `conflict` line per placed role that cannot be offered because another\n  offer on this node holds its endpoint name.\n  \"\"\"\n  fn status_text(node : Cap(ClusterNode.Live)) : String do\n    let st = state_of(node)\n    \"node \" ++ label(node) ++ \"\\n\"\n    ++ \"topology \" ++ Vault.get_or(st.strs, \"applied\", \"compiled\") ++ \"\\n\"\n    ++ \"offers \" ++ String.join(offered(node), \",\") ++ \"\\n\"\n    ++ \"draining \" ++ int_to_string(List.length(Vault.keys(st.draining))) ++ \"\\n\"\n    ++ \"running \" ++ int_to_string(running(node)) ++ \"\\n\"\n    ++ offer_lines(st) ++ drain_lines(st) ++ conflict_lines(st)\n  end\n\n  -- One `conflict <role> held-by <roles|unknown>` line per role placed here\n  -- that cannot be offered because another offer on this node holds its\n  -- endpoint name (`open_role`).\n  pfn conflict_lines(st : TopoState) : String do\n    let roles : List(TopoRole) = Vault.get_or(st.roles, \"roles\", Nil)\n    let names = List.sort_by(List.map(roles, fn r -> r.name), fn (a, b) -> a < b)\n    String.join(List.filter_map(names, fn n ->\n      match Vault.get(st.strs, \"x:\" ++ n) do\n        Some(h) -> Some(\"conflict \" ++ n ++ \" held-by \" ++ h ++ \"\\n\")\n        None -> None\n      end), \"\")\n  end\n\n  -- One `offer <role> fp <fingerprint> sessions <n>` line per open offer: the\n  -- live sessions per protocol fingerprint (DD step 12a; the control plane's\n  -- Agent reports them, so a gate can wait on a fingerprint's sessions).\n  pfn offer_lines(st : TopoState) : String do\n    String.join(List.map(List.sort_by(Vault.all(st.offers), fn (a, b) -> Tuple.first(a) < Tuple.first(b)), fn kv ->\n      match kv do\n        (name, o) -> \"offer \" ++ name ++ \" fp \" ++ o.ap.fingerprint ++ \" sessions \" ++ int_to_string(active(o)) ++ \"\\n\"\n      end), \"\")\n  end\n\n  -- One `drain <key> fp <fingerprint> sessions <n> since <ms>` line per closed\n  -- offer still draining: how many of its sessions are left, and when it closed.\n  pfn drain_lines(st : TopoState) : String do\n    String.join(List.map(List.sort_by(Vault.all(st.draining), fn (a, b) -> Tuple.first(a) < Tuple.first(b)), fn kv ->\n      match kv do\n        (key, o) -> \"drain \" ++ key ++ \" fp \" ++ o.ap.fingerprint ++ \" sessions \" ++ int_to_string(active(o))\n                    ++ \" since \" ++ int_to_string(Vault.get_or(st.meta, \"t:\" ++ key, 0)) ++ \"\\n\"\n      end), \"\")\n  end\n\n  doc \"This node's name as the membership and the control plane know it.\"\n  fn node_name(node : Cap(ClusterNode.Live)) : String do label(node) end\n\n  -- Write the status to MARCH_TOPOLOGY_STATUS when it changed (atomically:\n  -- a temporary file renamed over it, so a reader never sees half).\n  pfn write_status(node : Cap(ClusterNode.Live), st : TopoState) : () do\n    match process_env(\"MARCH_TOPOLOGY_STATUS\") do\n      None -> ()\n      Some(path) ->\n        let text = status_text(node)\n        if Vault.get(st.strs, \"status\") == Some(text) do () else\n          let tmp = path ++ \".tmp\"\n          match File.write(tmp, text) do\n            Ok(_) ->\n              let _ = File.rename(tmp, path)\n              Vault.set(st.strs, \"status\", text)\n            Err(_) -> ()\n          end\n        end\n    end\n  end\n\n  -- \u2500\u2500 draining \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Stop placing and close every offer of [node] (running sessions finish):\n  what SIGTERM does under `drain_on_signal`. Returns at once.\n  \"\"\"\n  fn close_all(node : Cap(ClusterNode.Live)) : () do\n    let st = state_of(node)\n    Vault.set(st.meta, \"closing\", 1)\n    -- Withdraw from every ranked role's rendezvous ranking first, so the\n    -- other nodes re-offer a `count = n` role now instead of after this\n    -- node's whole drain plus SWIM's suspect timeout (4.2: losing a role is\n    -- a drain, not a cut). A brief duplicate offer is tolerated (D19), and\n    -- the sessions this node is running continue.\n    List.each(Vault.get_or(st.roles, \"roles\", Nil), fn r ->\n      if ranked(r.place) do mark(node, st, r.name, false) else () end)\n    List.each(Vault.all(st.offers), fn kv -> match kv do (name, o) -> retire(st, name, o) end)\n    -- And start no session of its own: a hook's task that initiates\n    -- sessions back to back now gets `Err(Left(\"draining\"))`, so the drain\n    -- can reach zero sessions instead of running to its hard deadline.\n    SessionNode.refuse_initiations(node)\n  end\n\n  doc \"\"\"\n  On SIGTERM or SIGINT: close every offer of [node] (new invitations are\n  refused) and refuse every new `initiate` on it (`Err(Left(\"draining\"))`),\n  drain every code epoch the process runs (running sessions end\n  at their next loop boundary, D27, and actors take the epoch drain's\n  deadlines), then exit 0 once no session is running. At [soft_ms] a drain\n  still waiting is reported; at [hard_ms] the process exits 1, naming how\n  many sessions it cut. A second signal escapes the watcher and stops the\n  process at once.\n  \"\"\"\n  fn drain_on_signal(node : Cap(ClusterNode.Live), soft_ms : Int, hard_ms : Int) : () do\n    Signal.watch(Signal.Term, fn -> drain(node, soft_ms, hard_ms))\n    Signal.watch(Signal.Int, fn -> drain(node, soft_ms, hard_ms))\n  end\n\n  doc \"\"\"\n  Drain [node] now, as SIGTERM does under `drain_on_signal`. Called again\n  while a drain runs (a second signal), it stops the process at once, with\n  status 1.\n  \"\"\"\n  fn drain(node : Cap(ClusterNode.Live), soft_ms : Int, hard_ms : Int) : () do\n    let st = state_of(node)\n    if Vault.get(st.meta, \"draining\") != None do\n      -- The runtime's own second-signal escape only ends an HTTP server's\n      -- loop, so without this a draining node ignored every further\n      -- SIGTERM until its hard deadline.\n      report(\"second signal: stopping \" ++ label(node) ++ \" now with \" ++ int_to_string(unfinished(node)) ++ \" session(s) still running\")\n      process_exit(1)\n    else if Vault.get(st.meta, \"closing\") != None do () else\n      Vault.set(st.meta, \"draining\", 1)\n      report(\"draining \" ++ label(node) ++ \" (soft \" ++ int_to_string(soft_ms) ++ \" ms, hard \"\n             ++ int_to_string(hard_ms) ++ \" ms)\")\n      close_all(node)\n      -- The epoch drain (DD step 6, follow-up 5): the same as the reload\n      -- server's `DRAIN` for every epoch this process runs. Sessions end at\n      -- their next loop boundary (D27); the hard deadline below exits the\n      -- process before the epoch drain's own would matter, so only the soft\n      -- one is armed here. (The stdlib-only builtin: this function has no\n      -- `Cap(IO)` and its signature is the generated main's.)\n      epoch_drain(soft_ms, 0)\n      let t0 = unix_time_ms()\n      let _ = task_spawn(fn _ -> drain_wait(node, soft_ms, hard_ms, t0, false))\n      ()\n    end end\n  end\n\n  pfn drain_wait(node : Cap(ClusterNode.Live), soft_ms : Int, hard_ms : Int, t0 : Int, warned : Bool) : Int do\n    let n = unfinished(node)\n    let spent = unix_time_ms() - t0\n    if n == 0 do\n      report(\"drained \" ++ label(node))\n      -- Leave the cluster (close the links and the listener) rather than\n      -- vanish: peers see the links close instead of waiting out a suspect\n      -- timeout.\n      ClusterNode.stop(node)\n      process_exit(0)\n      0\n    else if spent >= hard_ms do\n      report(\"hard deadline: stopping \" ++ label(node) ++ \" with \" ++ int_to_string(n) ++ \" session(s) still running\")\n      ClusterNode.stop(node)\n      process_exit(1)\n      1\n    else\n      let w = if not(warned) && spent >= soft_ms do\n        report(\"soft deadline passed with \" ++ int_to_string(n) ++ \" session(s) still running\")\n        true\n      else warned end\n      sleep_ms(50)\n      drain_wait(node, soft_ms, hard_ms, t0, w)\n    end end\n  end\n\n  -- \u2500\u2500 supervision \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Re-offer any role whose offer actor, or hosting actor, has died, and keep\n  the calling task (the generated `main`) alive until the node stops or\n  drains. A process whose `main` returned would exit, taking its offers\n  with it.\n  \"\"\"\n  fn supervise_offers(node : Cap(ClusterNode.Live)) : () do\n    let st = state_of(node)\n    Vault.set(st.meta, \"supervise\", 1)\n    supervise_wait(st)\n  end\n\n  @[diverges] pfn supervise_wait(st : TopoState) : () do\n    if Vault.get(st.meta, \"stopped\") != None do ()\n    else\n      sleep_ms(250)\n      supervise_wait(st)\n    end\n  end\n\n  doc \"\"\"\n  Stop [node] and everything placed on it: close every offer (running\n  sessions are cut when the node goes), end placement and `supervise_offers`,\n  then `ClusterNode.stop`. For a program (a test, say) that ends on its own\n  rather than on a signal.\n  \"\"\"\n  fn stop(node : Cap(ClusterNode.Live)) : () do\n    let st = state_of(node)\n    close_all(node)\n    Vault.set(st.meta, \"stopped\", 1)\n    ClusterNode.stop(node)\n  end\n\n  -- \u2500\u2500 hooks \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Run the pool hook [name] ([f]), which must return promptly: offers open\n  only after every hook has returned. A watchdog reports a hook still\n  running after MARCH_HOOK_TIMEOUT_MS (default 10000) and exits the process\n  with status 1: offering nothing would be worse than failing loudly.\n  Long-lived work belongs in a task or actor the hook spawns.\n  \"\"\"\n  fn hook(name : String, f : () -> a) : a do\n    let flag : Vault(Int) = Vault.new(\"topology_hook_\" ++ int_to_string(next_id()))\n    let limit = hook_timeout_ms()\n    let _ = task_spawn(fn _ -> watchdog(flag, name, limit, unix_time_ms()))\n    let v = f()\n    Vault.set(flag, \"done\", 1)\n    v\n  end\n\n  pfn watchdog(flag : Vault(Int), name : String, limit : Int, t0 : Int) : Int do\n    if Vault.get(flag, \"done\") != None do 0\n    else if unix_time_ms() - t0 >= limit do\n      report(\"hook \" ++ name ++ \" did not return within \" ++ int_to_string(limit)\n             ++ \" ms (MARCH_HOOK_TIMEOUT_MS); a hook must return promptly -- start long-lived work in a task or actor\")\n      process_exit(1)\n      1\n    else\n      sleep_ms(50)\n      watchdog(flag, name, limit, t0)\n    end end\n  end\n\n  -- \u2500\u2500 starting the node \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  The node's configuration from the environment (`ClusterNode.config_from_env`),\n  with defaults for a lone local run: MARCH_NODE_NAME defaults to `local-1`\n  and MARCH_NODE_PORT to 7946.\n\n  Without MARCH_NODE_CERT (shared-secret mode) it also reads the seeds from\n  MARCH_CLUSTER_NODES (comma-separated), MARCH_NODE_ADVERTISE, the secret\n  from MARCH_CLUSTER_SECRET (default `march-cluster`) and MARCH_NODE_CREATION\n  (default: the current Unix ms). With MARCH_NODE_CERT set, certificate mode\n  is read by `ClusterNode.config_from_env` instead, and a configuration it\n  rejects stops the program via `start_failed`.\n  \"\"\"\n  fn config_from_env() : ClusterNode.CnConfig do\n    if Env.is_set(\"MARCH_NODE_CERT\") do\n      -- Certificate mode (dd step 11): the node's certificate, key and the\n      -- operator's public key come from the environment, as `ClusterNode.config_from_env` reads them.\n      match ClusterNode.config_from_env() do\n        Ok(c) -> c\n        Err(e) -> start_failed(e)\n      end\n    else config_plain_from_env() end\n  end\n\n  pfn config_plain_from_env() : ClusterNode.CnConfig do\n    let name = Env.get(\"MARCH_NODE_NAME\", \"local-1\")\n    let port = Env.get_int(\"MARCH_NODE_PORT\", 7946)\n    let seeds = labels_of(Env.get(\"MARCH_CLUSTER_NODES\", \"\"))\n    let creation = Env.get_int(\"MARCH_NODE_CREATION\", unix_time_ms())\n    ClusterNode.config(name, port, Env.get(\"MARCH_NODE_ADVERTISE\", \"\"), seeds,\n                       Env.get(\"MARCH_CLUSTER_SECRET\", \"march-cluster\"), creation)\n  end\n\n  doc \"\"\"\n  Report that the node could not start ([why]) and stop the program with\n  status 1. The generated `main` starts the node itself --\n  `ClusterNode.start(io, Topology.config_from_env())` -- because only\n  `ClusterNode` may hand out a `Cap(ClusterNode.Live)`.\n  \"\"\"\n  fn start_failed(why : String) : a do\n    report(why)\n    process_exit(1)\n    panic(why)\n  end\n\n  doc \"\"\"\n  Whether this process runs pool [pool]: MARCH_POOLS (comma-separated) names\n  the pools a process of a shared build runs; unset, it runs every pool the\n  build contains (`forge run`'s one process, D9), as it does when MARCH_POOLS\n  names no pool at all (empty or only commas).\n  \"\"\"\n  fn runs_pool(pool : String) : Bool do\n    match process_env(\"MARCH_POOLS\") do\n      None -> true\n      Some(s) ->\n        let ps = labels_of(s)\n        List.is_empty(ps) || List.member(ps, pool)\n    end\n  end\nend\n";
